/* ML Model Hub — olive green theme */
:root {
  --olive-50:  #f7f8ed;
  --olive-100: #ebedcf;
  --olive-300: #b7c06a;
  --olive-500: #7d8a2a;   /* primary olive */
  --olive-600: #667118;
  --olive-700: #4f560f;
  --olive-900: #2c3008;
  --bg:        #1a1d10;     /* dark olive-black */
  --card:      #22271a;
  --text:      #eef0dd;
  --muted:     #b9bd9a;
  --border:    #3a4220;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  min-height: 100vh;
}

a { color: var(--olive-300); text-decoration: none; }
a:hover { text-decoration: underline; }

/* Navbar */
.navbar {
  background: linear-gradient(135deg, var(--olive-700), var(--olive-900));
  border-bottom: 2px solid var(--olive-500);
  padding: 0.9rem 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky; top: 0; z-index: 10;
}
.navbar .brand {
  font-size: 1.3rem;
  font-weight: 700;
  color: var(--olive-100);
  letter-spacing: 0.5px;
}
.navbar .brand span { color: var(--olive-300); }
.navbar nav a {
  color: var(--text);
  margin-left: 1.4rem;
  font-weight: 500;
  padding: 0.4rem 0.7rem;
  border-radius: 6px;
  transition: background 0.2s;
}
.navbar nav a:hover { background: var(--olive-600); text-decoration: none; }

/* Layout */
.container { max-width: 1100px; margin: 0 auto; padding: 2rem 1.5rem; }

.hero {
  text-align: center;
  padding: 4rem 1rem;
  background: radial-gradient(circle at 50% 0%, var(--olive-700) 0%, var(--bg) 70%);
  border-radius: 12px;
  margin-bottom: 2rem;
}
.hero h1 {
  font-size: 2.6rem;
  color: var(--olive-100);
  margin-bottom: 0.8rem;
}
.hero p { color: var(--muted); font-size: 1.15rem; max-width: 600px; margin: 0 auto; }

/* Cards / features */
.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 1.4rem;
  margin-top: 1.5rem;
}
.card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 1.6rem;
  transition: transform 0.2s, border-color 0.2s;
}
.card:hover { transform: translateY(-4px); border-color: var(--olive-500); }
.card h3 { color: var(--olive-300); margin-bottom: 0.5rem; }
.card p { color: var(--muted); }

/* Buttons */
.btn {
  display: inline-block;
  background: var(--olive-500);
  color: var(--olive-50);
  padding: 0.7rem 1.4rem;
  border-radius: 8px;
  font-weight: 600;
  border: none;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}
.btn:hover { background: var(--olive-600); text-decoration: none; }
.btn:active { transform: scale(0.97); }
.btn-large { font-size: 1.05rem; padding: 0.9rem 2rem; }
.btn-danger { background: #8a3a2a; }
.btn-danger:hover { background: #a04530; }

/* Forms */
.form-card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 2rem;
  max-width: 640px;
  margin: 0 auto;
}
.form-group { margin-bottom: 1.3rem; }
.form-group label {
  display: block;
  margin-bottom: 0.45rem;
  color: var(--olive-100);
  font-weight: 500;
}
.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: 0.7rem 0.9rem;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text);
  font-size: 0.95rem;
}
.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--olive-500);
  box-shadow: 0 0 0 3px rgba(125, 138, 42, 0.2);
}
.form-group textarea { resize: vertical; min-height: 80px; }

/* Drop zone */
.dropzone {
  border: 2px dashed var(--olive-500);
  border-radius: 10px;
  padding: 2.5rem 1rem;
  text-align: center;
  color: var(--muted);
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s;
  background: var(--bg);
}
.dropzone:hover, .dropzone.drag {
  background: var(--card);
  border-color: var(--olive-300);
  color: var(--text);
}
.dropzone input[type=file] { display: none; }
.dropzone .file-name { margin-top: 0.6rem; color: var(--olive-300); font-weight: 600; }

/* Model list table */
.table-wrap { overflow-x: auto; }
table {
  width: 100%;
  border-collapse: collapse;
  background: var(--card);
  border-radius: 10px;
  overflow: hidden;
}
th, td { padding: 0.85rem 1rem; text-align: left; border-bottom: 1px solid var(--border); }
th { background: var(--olive-700); color: var(--olive-50); font-weight: 600; }
tr:hover td { background: var(--olive-900); }
.badge {
  display: inline-block;
  padding: 0.25rem 0.6rem;
  border-radius: 20px;
  font-size: 0.78rem;
  font-weight: 600;
  text-transform: capitalize;
}
.badge-huggingface { background: #ffb700; color: #2c1a00; }
.badge-kaggle      { background: #20beff; color: #002433; }
.badge-local       { background: var(--olive-300); color: var(--olive-900); }

/* Flash / status message */
.flash {
  padding: 0.9rem 1.2rem;
  border-radius: 8px;
  margin-bottom: 1.2rem;
  font-weight: 500;
}
.flash.ok  { background: rgba(125,138,42,0.2); border: 1px solid var(--olive-500); color: var(--olive-100); }
.flash.err { background: rgba(138,58,42,0.25); border: 1px solid #8a3a2a; color: #ffd0c5; }

/* Empty state */
.empty {
  text-align: center;
  padding: 3rem 1rem;
  color: var(--muted);
}
.empty a { font-weight: 600; }

footer {
  text-align: center;
  padding: 2rem;
  color: var(--muted);
  font-size: 0.85rem;
  border-top: 1px solid var(--border);
  margin-top: 2rem;
}

.page-title {
  font-size: 1.8rem;
  color: var(--olive-100);
  margin-bottom: 1rem;
}
.actions { margin-top: 1.5rem; }

{% extends "base.html" %}
{% block title %}Upload Model — ML Model Hub{% endblock %}

{% block content %}
<h1 class="page-title">Upload a Model</h1>
<div id="flash"></div>

<form id="upload-form" class="form-card" enctype="multipart/form-data">
  <div class="form-group">
    <label for="name">Model Name *</label>
    <input type="text" id="name" name="name" required placeholder="e.g. bert-base-uncased" />
  </div>

  <div class="form-group">
    <label for="source">Source</label>
    <select id="source" name="source">
      <option value="huggingface">HuggingFace</option>
      <option value="kaggle">Kaggle</option>
      <option value="local">Local</option>
    </select>
  </div>

  <div class="form-group">
    <label for="description">Description</label>
    <textarea id="description" name="description" placeholder="Short note about the model..."></textarea>
  </div>

  <div class="form-group">
    <label>Model File *</label>
    <div class="dropzone" id="dropzone">
      <input type="file" id="file" name="file" required />
      <p>Drag & drop your model file here, or click to select</p>
      <p class="file-name" id="file-name">No file selected</p>
    </div>
  </div>

  <button type="submit" class="btn btn-large">Upload Model</button>
</form>
{% endblock %}

{% block scripts %}
<script>
const dz = document.getElementById('dropzone');
const fileInput = document.getElementById('file');
const fileName = document.getElementById('file-name');
const flash = document.getElementById('flash');
const form = document.getElementById('upload-form');

['dragover','dragenter'].forEach(ev => dz.addEventListener(ev, e => {
  e.preventDefault(); dz.classList.add('drag');
}));
['dragleave','drop'].forEach(ev => dz.addEventListener(ev, e => {
  e.preventDefault(); dz.classList.remove('drag');
}));
dz.addEventListener('drop', e => {
  if (e.dataTransfer.files.length) {
    fileInput.files = e.dataTransfer.files;
    fileName.textContent = fileInput.files[0].name;
  }
});
dz.addEventListener('click', () => fileInput.click());
fileInput.addEventListener('change', () => {
  fileName.textContent = fileInput.files[0] ? fileInput.files[0].name : 'No file selected';
});

form.addEventListener('submit', async (e) => {
  e.preventDefault();
  flash.innerHTML = '';
  if (!fileInput.files.length) {
    showFlash('Please choose a file.', 'err');
    return;
  }
  const fd = new FormData(form);
  try {
    const res = await fetch('/api/models/upload', { method: 'POST', body: fd });
    const data = await res.json();
    if (!res.ok) {
      showFlash(data.detail || 'Upload failed.', 'err');
      return;
    }
    showFlash(`Uploaded "${data.model.name}" (${data.model.size_mb} MB) successfully!`, 'ok');
    form.reset();
    fileName.textContent = 'No file selected';
  } catch (err) {
    showFlash('Network error: ' + err.message, 'err');
  }
});

function showFlash(msg, type) {
  flash.innerHTML = `<div class="flash ${type}">${msg}</div>`;
  flash.scrollIntoView({behavior:'smooth'});
}
</script>
{% endblock %}

{% extends "base.html" %}
{% block title %}Models — ML Model Hub{% endblock %}

{% block content %}
<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:.6rem;">
  <h1 class="page-title" style="margin:0;">Uploaded Models</h1>
  <a href="/upload" class="btn">+ Upload New</a>
</div>

<div id="flash"></div>

{% if models %}
<div class="table-wrap">
  <table>
    <thead>
      <tr>
        <th>Name</th>
        <th>Source</th>
        <th>Size</th>
        <th>Uploaded</th>
        <th>Description</th>
        <th>Actions</th>
      </tr>
    </thead>
    <tbody>
      {% for m in models %}
      <tr id="row-{{ m.id }}">
        <td><strong>{{ m.name }}</strong></td>
        <td><span class="badge badge-{{ m.source }}">{{ m.source }}</span></td>
        <td>{{ m.size_mb }} MB</td>
        <td>{{ m.uploaded_at[:10] }}</td>
        <td>{{ m.description or '—' }}</td>
        <td><button class="btn btn-danger" onclick="delModel('{{ m.id }}','{{ m.name }}')">Delete</button></td>
      </tr>
      {% endfor %}
    </tbody>
  </table>
</div>
{% else %}
<div class="empty">
  <p>No models uploaded yet.</p>
  <p><a href="/upload">Upload your first model →</a></p>
</div>
{% endif %}
{% endblock %}

{% block scripts %}
<script>
async function delModel(id, name) {
  if (!confirm(`Delete model "${name}"? This cannot be undone.`)) return;
  try {
    const res = await fetch(`/api/models/${id}`, { method: 'DELETE' });
    if (res.ok) {
      document.getElementById('row-' + id)?.remove();
      showFlash(`Deleted "${name}".`, 'ok');
    } else {
      const d = await res.json();
      showFlash(d.detail || 'Delete failed.', 'err');
    }
  } catch (e) {
    showFlash('Network error: ' + e.message, 'err');
  }
}
function showFlash(msg, type) {
  const f = document.getElementById('flash');
  f.innerHTML = `<div class="flash ${type}">${msg}</div>`;
}
</script>
{% endblock %}

